        story=[
            ("第1部 クリーの戦士ヴァース", "1995年、宇宙の帝国クリーの星ハラ。6年より前の記憶がない戦士ヴァースは、年上の女性が出てくる悪夢に悩まされている。\n隊長ヨン・ロッグと、クリーを治める人工知能スプリーム・インテリジェンスは、感情をおさえるよう求める。ヴァースは精鋭部隊スターフォースの仲間と、スパイを救う任務に出る。",
             "Part 1: Vers, a Kree warrior", "1995, on the Kree planet Hala. Vers, a warrior with no memories from before six years ago, is haunted by nightmares of an older woman.\nHer commander Yon-Rogg and the Supreme Intelligence, the AI that rules the Kree, urge her to keep her emotions in check. She heads out with her Starforce team to rescue a spy."),
            ("第2部 トルファの待ち伏せ", "救うはずのスパイは、姿を変えられる宇宙人スクラルの司令官タロスが化けた姿だった。ヴァースはさらわれ、記憶をのぞかれる。\nタロスは光の速さで飛べるエンジンの手がかりを探していた。ヴァースは逃げ出し、地球へ落ちていく。",
             "Part 2: The ambush on Torfa", "The spy turns out to be Talos, commander of the shapeshifting Skrulls, in disguise. Vers is taken and her memories are probed.\nTalos is hunting for a light-speed engine. Vers escapes and falls toward Earth."),
            ("第3部 1995年のロサンゼルス", "ヴァースはロサンゼルスのレンタルビデオ店に落ち、シールドの捜査官ニック・フューリーとコールソンに出会う。電車の上でスクラルと戦い、自分の記憶の入った結晶を取り戻す。\nコールソンに化けたスクラルが死に、フューリーは宇宙人がいると信じる。上司ケラーの命令で、フューリーはヴァースと手を組むが、ケラーの正体はタロスだった。",
             "Part 3: Los Angeles, 1995", "Vers crashes into a video store in Los Angeles and meets S.H.I.E.L.D. agents Nick Fury and Coulson. She fights a Skrull on a train and recovers a crystal holding her memories.\nAfter a Skrull posing as Coulson dies, Fury has to believe in aliens. On his boss Keller's orders he teams up with Vers, but Keller is really Talos."),
            ("第4部 ペガサス計画", "空軍の基地の記録から、悪夢の女性はウェンディ・ローソン博士で、ヴァースは1989年に博士と墜落して死んだことになっていたパイロットだと分かる。\nフューリーは偽のケラーに気づき、2人は猫のグースを連れ、ジェット機で逃げ出す。",
             "Part 4: Project Pegasus", "Records at an Air Force base reveal the woman in her nightmares is Dr. Wendy Lawson, and that Vers is the pilot declared dead with her in a 1989 crash.\nFury sees through the fake Keller, and the two escape in a jet with Goose the cat."),
            ("第5部 ルイジアナの親友", "親友マリアと娘モニカのもとで、ヴァースの本当の名前がキャロル・ダンヴァースだと分かる。武器を持たずに来たタロスは、スクラルはクリーに故郷を奪われた難民で、ローソン博士の正体はクリーの科学者マー・ベルだったと明かす。\n録音を聞いたキャロルは、ヨン・ロッグが博士を撃ち、自分がエンジンを壊してその力を浴び、クリーに連れ去られたことを思い出す。",
             "Part 5: Her best friend in Louisiana", "With her best friend Maria and Maria's daughter Monica, Vers learns her real name is Carol Danvers. Talos arrives unarmed and reveals that the Skrulls are refugees driven from their home by the Kree, and that Dr. Lawson was really the Kree scientist Mar-Vell.\nHearing a recording, Carol remembers: Yon-Rogg shot Lawson, Carol destroyed the engine and absorbed its energy, and the Kree took her."),
            ("第6部 宇宙の研究所", "地球の周りに隠された博士の研究所には、タロスの家族を含むスクラルたちとテッセラクトがあった。スターフォースに捕まったキャロルは、力をおさえる装置を外し、本当の力に目覚める。\n猫のグースの正体は宇宙の生き物フラーケンで、テッセラクトを飲みこみ、フューリーの左目をひっかく。",
             "Part 6: The lab in orbit", "Lawson's hidden lab in orbit shelters Skrulls, including Talos's family, and the Tesseract. Captured by Starforce, Carol removes the implant holding back her power and unleashes it.\nGoose turns out to be an alien Flerken, swallows the Tesseract and scratches out Fury's left eye."),
            ("第7部 空と宇宙の戦い", "マリアは追ってきたミン・エルヴァを撃ち落とす。キャロルは地球を狙うロナンの艦隊のミサイルと船を壊して追い払う。\n素手で戦えと挑発するヨン・ロッグを、キャロルは一撃で吹き飛ばし、ハラへ送り返す。",
             "Part 7: Battle in the sky and space", "Maria shoots down the pursuing Minn-Erva. Carol destroys the missiles and a ship of Ronan's fleet and drives it away from Earth.\nWhen Yon-Rogg dares her to fight without her powers, she blasts him with one shot and sends him back to Hala."),
            ("第8部 別れとアベンジャーズの始まり", "キャロルはスクラルの新しい故郷を探すため宇宙へ旅立ち、フューリーに改造したポケベルを渡す。フューリーは、ヒーローを集める計画に、キャロルの呼び名「アベンジャー」から名前を付ける。\nエンドクレジットの途中では2018年のアベンジャーズの前にキャロルが現れ、最後にはグースがテッセラクトを吐き出す。",
             "Part 8: Farewell, and the start of the Avengers", "Carol leaves to find the Skrulls a new home and gives Fury a modified pager. Fury names his plan to gather heroes after her call sign, \"Avenger.\"\nMid-credits, Carol appears before the Avengers in 2018; after the credits, Goose coughs up the Tesseract."),
        ],
        confusing=[
            ("なぜ「ヴァース」という名前だったの？",
             "事故のとき壊れた認識票（名前の入った金属の札）に、「キャロル・ダンヴァース」の一部の文字しか残っていなかったからです。クリーはそれを名前として使いました。",
             "Why was she called Vers?",
             "Her dog tag was broken in the crash, and only part of \"Carol Danvers\" was left on it. The Kree used that as her name."),
            ("スクラルは悪者じゃないの？",
             "この作品では、スクラルは故郷を失って逃げている人たちとして描かれます。クリーがスクラルを攻撃していたので、キャロルは最後にスクラルを助けます。",
             "Aren't the Skrulls the bad guys?",
             "In this film the Skrulls are refugees who have lost their home. The Kree were the ones attacking them, so Carol ends up helping the Skrulls."),
            ("スプリーム・インテリジェンスはなぜローソン博士の姿なの？",
             "会う人が一番尊敬する人の姿で現れるからです。キャロルは記憶をなくしていても、心の中でローソン博士を大切に思っていました。",
             "Why does the Supreme Intelligence look like Dr. Lawson?",
             "It appears as the person you admire most. Even without her memories, Carol still held Dr. Lawson close."),
            ("フューリーの目はなぜ両方ある？",
             "この作品はフューリーが片目を失う前の話だからです。最後に、猫のグースにひっかかれたことが原因だと分かります。",
             "Why does Fury have both eyes?",
             "This is before he loses one. At the end you find out it was Goose the cat who scratched it."),
            ("なぜキャロルはこの後しばらく地球に来ないの？",
             "スクラルの新しい故郷を探すため、宇宙の遠くへ旅立ったからです。本当に困ったときに呼べるよう、フューリーにポケベルを渡しています。",
             "Why doesn't Carol come back to Earth for years?",
             "She went far into space to help the Skrulls find a new home. She left Fury a pager so he could call her in a real emergency."),
            ("コールソンがいるのはなぜ？",
             "1995年のコールソンは、S.H.I.E.L.D.に入ったばかりの新人です。『アイアンマン』などに出てくる彼の、若いころの姿です。",
             "Why is Coulson here?",
             "In 1995 Coulson is a new S.H.I.E.L.D. agent. It's a younger version of the Coulson from Iron Man and later films."),
        ],
        points=[
            ("「アベンジャーズ」の名前の由来", "フューリーが計画の名前を決めるきっかけは、キャロルの戦闘機に書かれていた呼び名「アベンジャー」です。",
             "Where the name \"Avengers\" comes from", "Fury gets the name for his initiative from Carol's fighter-jet call sign, \"Avenger.\""),
            ("1990年代の小ネタ", "レンタルビデオ店、ポケベル、パソコンの遅さなど、1995年らしい物があちこちに出てきます。",
             "1990s details", "Video rental stores, pagers and painfully slow computers pop up throughout to set the 1995 mood."),
            ("マリアの娘モニカ", "マリアの娘モニカは、大人になって『ワンダヴィジョン』と『マーベルズ』に登場します。",
             "Maria's daughter Monica", "Maria's daughter Monica appears as an adult in WandaVision and The Marvels."),
            ("タロスとフューリーの関係はこの後も続く", "タロスとフューリーは、のちの作品でも一緒に登場します。",
             "Talos and Fury's story continues", "Talos and Fury turn up together again in later titles."),
            ("スタン・リーのカメオ出演", "マーベル・コミックの生みの親スタン・リーが、電車の中で台本を読む乗客として登場します。",
             "Stan Lee's cameo", "Marvel Comics legend Stan Lee appears as a passenger reading a script on a train."),
        ],
        next=[
            ("iron-man", "物語の時代順で次の作品。2010年、トニー・スタークがアイアンマンになる。", "Next in story order: in 2010, Tony Stark becomes Iron Man."),
            ("avengers", "フューリーが考えた「アベンジャーズ計画」が実現する作品。", "Fury's Avengers Initiative finally comes together."),
            ("the-marvels", "キャロルが主役の続編。大人になったモニカも登場する。", "Carol's sequel, featuring a grown-up Monica."),
        ],
        shop=[("キャプテン・マーベル Blu-ray", "キャプテン・マーベル Blu-ray", "Captain Marvel Blu-ray"),
              ("キャプテン・マーベルのフィギュア", "キャプテンマーベル フィギュア", "Captain Marvel Marvel Legends figure"),
              ("グース（猫）のグッズ", "キャプテンマーベル グース", "Captain Marvel Goose cat"),
              ("キャプテン・マーベルのレゴ", "レゴ キャプテンマーベル", "LEGO Captain Marvel")],
