            ("スタン・リーのカメオ出演", "マーベル・コミックの生みの親スタン・リーが、エキスポでトニーに間違えられる客として登場します。",
             "Stan Lee's cameo", "Marvel Comics legend Stan Lee appears at the Expo, where Tony mistakes him for someone else."),
