        summary_en=[
            "Wanda and Vision live as newlyweds in a town that looks like a classic TV sitcom.",
            "Each episode moves through the decades, from the 1950s to the 2000s.",
            "Why is Vision alive? The town's secret slowly comes out.",
        ],
        before=[
            ("『エンドゲーム』の後の話です", "ヴィジョンは『インフィニティ・ウォー』で命を落としています。そのことを覚えておくと、ふしぎさがよく分かります。"),
            ("最初はわざと昔のドラマ風です", "白黒の画面や笑い声の入った昔のホームドラマのように作られています。だんだん本当の話が見えてくるので、最初の数話はがまんして観てください。"),
            ("ドラマのシリーズです", "Disney+で配信されている、全9話の連続ドラマです。"),
            ("最終話の後に2つ映像があります", "どちらもこの後の作品につながります。"),
        ],
        before_en=[
            ("It's set after Endgame", "Vision died in Infinity War. Keep that in mind and the strangeness makes sense."),
            ("It starts as a classic sitcom on purpose", "Black-and-white, laugh track and all. Give the first few episodes time: the real story emerges."),
            ("It's a TV series", "Nine episodes, streaming on Disney+."),
            ("Two scenes after the finale", "Both lead into later stories."),
        ],
        glossary=[
            ("ウェストビュー", "ワンダとヴィジョンが暮らす、アメリカの小さな町。",
             "Westview", "The small American town where Wanda and Vision live."),
            ("ヘックス", "町を包む、目に見えない大きな壁。中では、外とはちがうきまりで世界が動いている。",
             "The Hex", "A giant invisible barrier around the town. Inside, the world runs by different rules."),
            ("ソード（S.W.O.R.D.）", "宇宙からの危機などを担当する組織。町の外で、異変を調べている。",
             "S.W.O.R.D.", "An agency handling threats such as those from space, investigating the town from outside."),
            ("スカーレット・ウィッチ", "伝説に語られる、とても強い魔女の呼び名。",
             "The Scarlet Witch", "The name of a legendary, immensely powerful witch."),
            ("混沌の魔術（ケイオス・マジック）", "現実そのものを作り変えられる、特別な魔術。",
             "Chaos magic", "A rare magic that can reshape reality itself."),
        ],
        story=[
            ("第1話 公開収録でお送りします", "白黒の1950年代のホームドラマのような町ウェストビューで、ワンダとヴィジョンは新婚生活を始める。2人は力をかくして町になじもうとし、ヴィジョンの上司ハート夫妻を夕食に招く。\n食卓で、どこから来たのかと聞かれても2人は答えられず、ハート氏は食べ物をのどにつまらせる。一瞬、笑い声も音楽も消えて画面が冷たくなるが、ヴィジョンが助けると元に戻る。最後に、その番組を誰かが今の時代の機械で見ていると分かる。",
             "Episode 1: Filmed Before a Live Studio Audience", "In Westview, a town that looks like a black-and-white 1950s sitcom, Wanda and Vision begin married life. Hiding their powers, they host Vision's boss, Mr. Hart, and his wife for dinner.\nAsked where they came from, the couple can't answer, and Mr. Hart chokes. For a moment the laugh track and music vanish and the mood turns cold, until Vision saves him and everything snaps back. At the end, someone is watching the show on modern equipment."),
            ("第2話 チャンネルはそのまま", "1960年代風の町で、2人は町の出し物で手品を見せる。白黒の世界に色のついたおもちゃのヘリコプターが現れ、ラジオからワンダを呼ぶ声が聞こえる。\nガムを飲みこんで酔ったようになったヴィジョンを、ワンダは本物の魔法でかばい、舞台は大受けする。家に帰るとワンダは急に妊娠している。マンホールから養蜂家の服の男が出てくると、ワンダは場面を巻き戻し、世界はカラーになる。",
             "Episode 2: Don't Touch That Dial", "In a 1960s-style town, the couple perform a magic act at a talent show. A toy helicopter in color appears in the black-and-white world, and a voice on the radio calls for Wanda.\nWhen Vision swallows gum and acts drunk, Wanda covers with real magic, and the act is a hit. Back home, Wanda is suddenly pregnant. When a man in a beekeeper suit climbs out of a manhole, she rewinds the scene, and the world turns to color."),
            ("第3話 カラー放送", "1970年代風のカラーの町。ワンダの妊娠はあっという間に進み、力があばれて町じゅうが停電する。隣人ジェラルディンの手を借りて、双子のトミーとビリーが生まれる。\nジェラルディンが、ワンダの兄ピエトロがウルトロンに殺されたことを口にすると、ワンダの顔色が変わる。ジェラルディンは姿を消し、町の外の光の壁からはじき出されて、組織ソードの隊員たちに囲まれる。",
             "Episode 3: Now in Color", "Now in 1970s color, Wanda's pregnancy races ahead and her powers cause a town-wide blackout. With neighbor Geraldine's help, she gives birth to twins, Tommy and Billy.\nWhen Geraldine mentions that Wanda's brother Pietro was killed by Ultron, Wanda turns cold. Geraldine vanishes and is thrown out through a wall of static outside town, where S.W.O.R.D. agents surround her."),
            ("第4話 番組を中断します", "ジェラルディンの正体は、指パッチンから戻ったソードの隊員モニカ・ランボーだった。町の行方不明事件を調べに来たモニカは、町を包む見えない壁に吸いこまれていた。\n町の外にはソードの基地ができ、FBIのジミー・ウーと科学者ダーシーが、町からホームドラマ『ワンダヴィジョン』が放送されていることを見つける。死んだはずのヴィジョンが生きていることも分かる。基地に戻ったモニカは、すべてを動かしているのはワンダだと告げる。",
             "Episode 4: We Interrupt This Program", "Geraldine is really S.W.O.R.D. agent Monica Rambeau, back from the Blip. Investigating missing persons in Westview, she was pulled through an invisible barrier around the town.\nOutside, S.W.O.R.D. sets up a base, and FBI agent Jimmy Woo and scientist Darcy discover the town is broadcasting a sitcom called WandaVision, and that Vision, who died, is alive. Back at the base, Monica tells them Wanda is behind it all."),
            ("第5話 問題エピソード", "1980年代風の家で、双子はあっという間に10歳ほどに育ち、飼い始めた犬スパーキーは死んでしまう。\n町の外では、ソードの長官代理ヘイワードが、ワンダがヴィジョンの遺体を盗んだと言い、ドローンでワンダを撃とうとする。ワンダは壁の外へ出てきて、かまうなと警告する。会社で町の秘密に気づいたヴィジョンはワンダを問いつめる。そのとき、死んだはずの兄ピエトロが、別人の顔で玄関に現れる。",
             "Episode 5: On a Very Special Episode...", "In a 1980s-style home, the twins age up to about ten, and their new dog Sparky dies.\nOutside, Acting Director Hayward claims Wanda stole Vision's body and sends a drone to kill her. Wanda walks out of the barrier and warns him off. Having learned the town's secret at work, Vision confronts Wanda. Then her dead brother Pietro arrives at the door, with a different face."),
            ("第6話 ハロウィーンの不気味な夜に", "ハロウィーンの夜、ワンダは双子とピエトロとお菓子をもらいに出かけ、トミーにも速く走る力があると分かる。見回りに出たヴィジョンは、町のはずれで止まったままの住人たちを見つけ、外へ出ようとして体がくずれ始める。\n町の外では、ヘイワードに追い出されたモニカたちが、ヘイワードがヴィジョンの体を追っていたことを知る。ワンダはヴィジョンを救うため壁を大きく広げ、ソードの基地とダーシーたちまで飲みこむ。",
             "Episode 6: All-New Halloween Spooktacular!", "On Halloween, Wanda takes the twins and Pietro trick-or-treating, and Tommy turns out to have super-speed. On patrol, Vision finds residents frozen at the edge of town and, trying to leave, begins to disintegrate.\nOutside, Monica and her allies, thrown off the base, learn Hayward has been tracking Vision's body. To save Vision, Wanda expands the barrier, swallowing the S.W.O.R.D. base and Darcy."),
            ("第7話 第4の壁を破って", "2000年代の終わり風の家で、ワンダの力は思いどおりにならなくなる。サーカスの中で目覚めたヴィジョンは、ダーシーから自分がすでに死んでいることを聞く。\nモニカはひとりで壁を通りぬけ、特別な力を身につけてワンダに警告しに行くが、ワンダは信じない。双子をあずかっていたアグネスの家の地下で、アグネスは自分が魔女アガサ・ハークネスだと明かす。スパーキーを殺したのも、ピエトロを送りこんだのもアガサだった。",
             "Episode 7: Breaking the Fourth Wall", "In a late-2000s style, Wanda loses control of her reality. Vision wakes in a circus and learns from Darcy that he is dead.\nMonica crosses the barrier on her own, gains powers, and warns Wanda, who doesn't believe her. In the basement of Agnes's house, where the twins were left, Agnes reveals she is the witch Agatha Harkness. She killed Sparky and sent \"Pietro.\""),
            ("第8話 前回までは", "1693年のセイラムで、アガサは自分を裁こうとした母たち魔女の力と命を吸い取っていた。現代のアガサは、ワンダと一緒にワンダの記憶をたどる。\nソコヴィアで両親を失った日、ヒドラのマインド・ストーンの実験、アベンジャーズの基地でヴィジョンと悲しみについて話した日。そしてヴィジョンの死後、ソードで遺体を見せられたあと、ヴィジョンが買っていた空き地で悲しみがあふれ、町を作り変えたことが分かる。アガサは、ワンダこそ伝説のスカーレット・ウィッチだと告げる。",
             "Episode 8: Previously On", "In Salem in 1693, Agatha drained the magic and lives of the coven, led by her mother, who tried to execute her. In the present, she walks Wanda through her memories.\nThe day her parents died in Sokovia, Hydra's Mind Stone experiments, and the day at the Avengers Compound when Vision talked with her about grief. After Vision's death, having seen his body at S.W.O.R.D., Wanda went to the lot Vision had bought, and her grief remade the town. Agatha tells her she is the legendary Scarlet Witch."),
            ("第9話 シリーズ最終回", "ワンダはアガサと空で戦い、町ではワンダのヴィジョンと、ソードが組み直した白いヴィジョンが戦う。白いヴィジョンは記憶を取り戻して飛び去り、モニカはヘイワードの銃から双子を守る。\nワンダはルーンの罠でアガサから力を取り戻してスカーレット・ウィッチになり、アガサを隣人アグネスとして町に閉じこめる。ワンダは壁を消して町の人たちを解放し、ヴィジョンと双子に別れを告げる。最後の映像で、山小屋で魔術書を読むワンダに、双子の助けを呼ぶ声が聞こえる。",
             "Episode 9: The Series Finale", "Wanda battles Agatha in the sky while her Vision fights the White Vision S.W.O.R.D. rebuilt. The White Vision regains his memories and leaves, and Monica shields the twins from Hayward's bullets.\nUsing runes, Wanda takes back her power from Agatha, becomes the Scarlet Witch, and traps Agatha as neighbor Agnes. She takes down the barrier, freeing the town, and says goodbye to Vision and the twins. In the final scene, studying a book of magic in a cabin, Wanda hears her sons calling for help."),
        ],
        confusing=[
            ("なぜヴィジョンが生きているの？",
             "町にいるヴィジョンは、悲しみにくれたワンダが自分の力で作り出した存在です。",
             "Why is Vision alive?",
             "The Vision in town is one Wanda created with her own power out of grief."),
            ("町の人たちはどうなっていたの？",
             "ワンダの力で、ドラマの登場人物の役を演じさせられていました。本人たちはとても苦しんでいました。",
             "What happened to the townspeople?",
             "Wanda's power forced them to play roles in her sitcom, and they suffered for it."),
            ("白いヴィジョンは？",
             "ソードが本物のヴィジョンの体を組み直して作った存在です。最後は記憶を取り戻して飛び去ります。",
             "What's the White Vision?",
             "S.W.O.R.D. rebuilt the real Vision's body. In the end, he regains his memories and flies away."),
            ("モニカはどうなったの？",
             "町の壁を何度も通り抜けたことで、特別な力を得ます。キャロルの映画『マーベルズ』に続きます。",
             "What happened to Monica?",
             "Passing through the Hex gave her powers. Her story continues in The Marvels."),
        ],
        points=[
            ("時代ごとの演出", "話ごとに、その時代のテレビドラマの画面の大きさ、色、オープニングの歌がまねされています。",
             "Era-by-era style", "Each episode imitates the screen shape, color and theme songs of TV shows from its decade."),
            ("CMの場面", "途中に入る昔風のCMには、ワンダの過去にまつわるものがかくれています。",
             "The commercials", "The retro commercials hide nods to Wanda's past."),
            ("アグネスの歌", "第7話で流れる歌は、とても人気になりました。",
             "Agnes's song", "The song in Episode 7 became a big hit with fans."),
        ],
        next=[
            ("shang-chi", "物語の時代順で次の作品。", "Next in story order."),
            ("multiverse-of-madness", "ワンダのその後が描かれる。", "Wanda's story continues."),
            ("agatha-all-along", "隣人アグネスが主役のドラマ。", "The series starring Agnes."),
        ],
        shop=[("ワンダヴィジョンのグッズ", "ワンダヴィジョン グッズ", "WandaVision merchandise"),
              ("スカーレット・ウィッチのフィギュア", "スカーレットウィッチ フィギュア", "Scarlet Witch Marvel Legends figure"),
              ("ヴィジョンのフィギュア", "ヴィジョン マーベル フィギュア", "Vision Marvel Legends figure")],
