            ("X-MEN", "プロフェッサーXの屋敷を拠点にするミュータントのチーム。この映画ではコロッサスと見習いのネガソニックが出てくる。",
             "The X-Men", "A team of mutants based at Professor X's mansion. Here, only Colossus and his trainee Negasonic appear."),
