            ("第5部 ケーブルと手を組む", "ケーブルが、ウェイドとドミノに手を組もうと持ちかける。未来では、院長を殺したラッセルが、やがてケーブルの妻と娘を殺していた。\nウェイドは「まず説得させてくれ」という条件で受け入れ、一行は孤児院へ向かう。",
             "Part 5: Teaming up with Cable", "Cable proposes teaming up with Wade and Domino. In his future, Russell's first killing, the headmaster, leads to him murdering Cable's wife and daughter.\nWade agrees, on the condition that he gets to try talking Russell down first, and they head to the orphanage."),
